// Builds work/evidence-manifest.json. Static. Commands 01-05 are hashed in full.
// This command's out, err, and exit are written by the wrapper after exit and are sealed next.
// Do not edit this file after it has run.
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';

function fileRec(name) {
  const data = readFileSync(resolve(name));
  return { path: name.replaceAll('\\', '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}
function walk(dir, acc) {
  for (const name of readdirSync(dir)) {
    const abs = join(dir, name);
    if (statSync(abs).isDirectory()) walk(abs, acc);
    else acc.push(relative(resolve('.'), abs).replaceAll('\\', '/'));
  }
}
function commandRec(n) {
  const nn = String(n).padStart(2, '0');
  const exitDoc = JSON.parse(readFileSync(resolve('work/out/cmd/' + nn + '.exit'), 'utf8'));
  const cmdText = readFileSync(resolve('work/out/cmd/' + nn + '.cmd.txt'), 'utf8');
  return {
    n,
    requested: (cmdText.match(/^requested: (.*)$/m) || [])[1] || '',
    status: exitDoc.status,
    wrapper_sha256: exitDoc.wrapper_sha256,
    scripts: exitDoc.scripts || [],
    files: {
      cmd: fileRec('work/out/cmd/' + nn + '.cmd.txt'),
      out: fileRec('work/out/cmd/' + nn + '.out'),
      err: fileRec('work/out/cmd/' + nn + '.err'),
      exit: fileRec('work/out/cmd/' + nn + '.exit'),
    },
  };
}

const inputs = [
  'brief.md',
  'TASK.md',
  'templates/result.md',
  'inputs/00_0100_50000020.decoded.bin',
  'inputs/02_0106_458c0020.decoded.bin',
  'ref/PROJECT-STATE.md',
  'ref/analysis/button-af/AFON-MENU-RESEARCH.md',
  'ref/analysis/button-af/readiness/t6-afon-target-size-position/out/design.md',
  'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/out/profile-layout.md',
  'ref/analysis/button-af/readiness/t4b-afon-boot-order/README.md',
  'ref/tasks/T2-cell-ownership/decision.md',
  'ref/tasks/T2b-cell-ownership-gaps/decision.md',
  'ref/tasks/T2b-cell-ownership-gaps/run-20261118-062119-review/review.md',
  'ref/tasks/T2-cell-ownership/run-20261117-220544/work/out/verdict-v2.md',
  'ref/tasks/T2b-cell-ownership-gaps/run-20261118-053855/work/out/verdict-v4.md',
  'ref/tasks/T3j-afon-acceptance-assertions/brief.md',
  'ref/tasks/T5-afon-button-handoff/brief.md',
  'ref/tasks/T6-afon-target-size-position/brief.md',
  'ref/tasks/T6-afon-target-size-position/decision.md',
  'ref/tasks/T8-afon-integrated-acceptance/decision.md',
  'ref/tasks/T3l-afon-editor-completion/run-20261119-083228/work/out/design.md',
];
for (const path of inputs) if (!existsSync(resolve(path))) throw new Error('missing input ' + path);

const outputPaths = [];
walk(resolve('work/out'), outputPaths);
outputPaths.sort();
const outputs = ['work/result.md', ...outputPaths].map(fileRec);
const sources = [];
const scriptPaths = [];
walk(resolve('work/scripts'), scriptPaths);
scriptPaths.sort();
for (const path of scriptPaths) sources.push(fileRec(path));

const commands = [];
for (let n = 1; n <= 5; n++) commands.push(commandRec(n));

let pythonVersion = '';
try {
  pythonVersion = execFileSync('python', ['-I', '-c', 'import sys; print(sys.version)'], { encoding: 'utf8' }).trim();
} catch (err) {
  pythonVersion = String(err);
}

const doc = {
  task: 'T10-afon-profile-storage-5b82',
  brief_sha256: fileRec('brief.md').sha256,
  emulator_modules: [],
  experiment_versions: 0,
  note: 'No emulator process ran. The requirement guard stopped the task before a codec and before persistence. Commands 01-05 are hashed in full. Command 06 is this manifest; its out, err, and exit are in the external seal.',
  inputs: inputs.map(fileRec),
  sources,
  outputs,
  commands,
  tool_versions: {
    node: process.version,
    python: pythonVersion,
  },
};
writeFileSync(resolve('work/evidence-manifest.json'), JSON.stringify(doc, null, 2) + '\n');
process.stdout.write(JSON.stringify({
  ok: true,
  inputs: doc.inputs.length,
  sources: sources.length,
  outputs: outputs.length,
  commands: commands.length,
  brief_sha256: doc.brief_sha256,
}) + '\n');
